CREATE TABLE IF NOT EXISTS "users" ("id" TEXT NOT NULL, "last_modified_date" TEXT NULL, "created_date" TEXT NULL, "username" TEXT NOT NULL UNIQUE, "first_name" TEXT NULL, "last_name" TEXT NULL, "mobile" TEXT NULL, "email" TEXT NULL, "lang_key" TEXT NULL, "activated" INTEGER NOT NULL CHECK ("activated" IN (0, 1)), "image_url" TEXT NULL, "authorities" TEXT NOT NULL, "submission_count" INTEGER NULL, "assignment_count" INTEGER NULL, "org_unit_count" INTEGER NULL, "activity_u_i_ds" TEXT NOT NULL, "user_teams_u_i_ds" TEXT NOT NULL, "managed_teams_u_i_ds" TEXT NOT NULL, "user_groups_u_i_ds" TEXT NOT NULL, "user_forms_u_i_ds" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "org_units" ("id" TEXT NOT NULL, "last_modified_date" TEXT NULL, "created_date" TEXT NULL, "display_name" TEXT NULL, "label" TEXT NULL, "translations" TEXT NOT NULL, "name" TEXT NOT NULL, "code" TEXT NULL, "path" TEXT NOT NULL, "level" INTEGER NOT NULL, "parent" TEXT NULL REFERENCES org_units (id), PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "ou_levels" ("id" TEXT NOT NULL, "last_modified_date" TEXT NULL, "created_date" TEXT NULL, "display_name" TEXT NULL, "label" TEXT NULL, "translations" TEXT NOT NULL, "name" TEXT NOT NULL, "code" TEXT NULL, "level" INTEGER NOT NULL, "offline_levels" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "projects" ("id" TEXT NOT NULL, "last_modified_date" TEXT NULL, "created_date" TEXT NULL, "display_name" TEXT NULL, "label" TEXT NULL, "translations" TEXT NOT NULL, "name" TEXT NOT NULL, "code" TEXT NULL, "disabled" INTEGER NULL CHECK ("disabled" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "activities" ("id" TEXT NOT NULL, "last_modified_date" TEXT NULL, "created_date" TEXT NULL, "display_name" TEXT NULL, "label" TEXT NULL, "translations" TEXT NOT NULL, "name" TEXT NOT NULL, "code" TEXT NULL, "project" TEXT NOT NULL REFERENCES projects (id), "disabled" INTEGER NULL CHECK ("disabled" IN (0, 1)), "start_date" TEXT NULL, "end_date" TEXT NULL, "description" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "teams" ("id" TEXT NOT NULL, "last_modified_date" TEXT NULL, "created_date" TEXT NULL, "code" TEXT NULL, "disabled" INTEGER NULL CHECK ("disabled" IN (0, 1)), "activity" TEXT NOT NULL REFERENCES activities (id), PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "managed_teams" ("id" TEXT NOT NULL, "last_modified_date" TEXT NULL, "created_date" TEXT NULL, "code" TEXT NULL, "activity" TEXT NOT NULL REFERENCES activities (id), "managed_by" TEXT NOT NULL REFERENCES teams (id), PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "assignments" ("id" TEXT NOT NULL, "last_modified_date" TEXT NULL, "created_date" TEXT NULL, "activity" TEXT NOT NULL REFERENCES activities (id), "team" TEXT NOT NULL REFERENCES teams (id), "org_unit" TEXT NOT NULL REFERENCES org_units (id), "instance_date" TEXT NULL, "sync_state" TEXT NOT NULL, "status" TEXT NULL, "completed_date" TEXT NULL, "updated_at_client" TEXT NULL, "disabled" INTEGER NULL CHECK ("disabled" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "form_templates" ("id" TEXT NOT NULL, "version_uid" TEXT NOT NULL, "version_number" INTEGER NOT NULL, "name" TEXT NOT NULL, "label" TEXT NULL, "description" TEXT NULL, "disabled" INTEGER NULL CHECK ("disabled" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "assignment_forms" ("assignment" TEXT NOT NULL REFERENCES assignments (id) ON UPDATE CASCADE, "form" TEXT NOT NULL REFERENCES form_templates (id), "can_add_submissions" INTEGER NULL CHECK ("can_add_submissions" IN (0, 1)), "can_view_submissions" INTEGER NULL CHECK ("can_view_submissions" IN (0, 1)), "can_edit_submissions" INTEGER NULL CHECK ("can_edit_submissions" IN (0, 1)), "can_delete_submissions" INTEGER NULL CHECK ("can_delete_submissions" IN (0, 1)), PRIMARY KEY ("assignment", "form"));
CREATE TABLE IF NOT EXISTS "form_template_versions" ("id" TEXT NOT NULL, "template" TEXT NOT NULL REFERENCES form_templates (id), "version_number" INTEGER NOT NULL, "fields" TEXT NOT NULL, "sections" TEXT NOT NULL, "options" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "metadata_submissions" ("id" TEXT NOT NULL, "last_modified_date" TEXT NULL, "created_date" TEXT NULL, "resource_type" TEXT NOT NULL, "metadata_schema" TEXT NOT NULL, "serial_number" INTEGER NOT NULL, "version" INTEGER NOT NULL, "resource_id" TEXT NOT NULL, "form_data" TEXT NULL, "created_by" TEXT NULL, "last_modified_by" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "data_instances" ("id" TEXT NOT NULL, "last_modified_date" TEXT NULL, "created_date" TEXT NULL, "deleted" INTEGER NOT NULL CHECK ("deleted" IN (0, 1)), "deleted_at" TEXT NULL, "form_template" TEXT NOT NULL REFERENCES form_templates (id), "template_version" TEXT NOT NULL REFERENCES form_template_versions (id), "assignment" TEXT NULL REFERENCES assignments (id), "start_entry_time" TEXT NOT NULL, "finished_entry_time" TEXT NULL, "form_data" TEXT NULL, "updated_at_client" TEXT NULL, "sync_state" TEXT NOT NULL, "last_sync_date" TEXT NULL, "last_sync_message" TEXT NULL, "is_to_update" INTEGER NOT NULL CHECK ("is_to_update" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "repeat_instances" ("id" TEXT NOT NULL DEFAULT '01ky19w2sagxs1ke2wmwgv42ck', "last_modified_date" TEXT NULL, "created_date" TEXT NULL, "submission" TEXT NOT NULL REFERENCES data_instances (id), "parent" TEXT NULL REFERENCES repeat_instances (id), "template_path" TEXT NOT NULL, "repeat_index" INTEGER NOT NULL, "deleted" INTEGER NOT NULL DEFAULT 0 CHECK ("deleted" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "data_option_sets" ("id" TEXT NOT NULL, "last_modified_date" TEXT NULL, "created_date" TEXT NULL, "display_name" TEXT NULL, "label" TEXT NULL, "translations" TEXT NOT NULL, "name" TEXT NOT NULL, "code" TEXT NULL, "deleted_at" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "data_elements" ("id" TEXT NOT NULL, "last_modified_date" TEXT NULL, "created_date" TEXT NULL, "display_name" TEXT NULL, "label" TEXT NULL, "translations" TEXT NOT NULL, "name" TEXT NOT NULL, "code" TEXT NULL, "description" TEXT NULL, "type" TEXT NOT NULL, "option_set" TEXT NULL REFERENCES data_option_sets (id), "mandatory" INTEGER NULL CHECK ("mandatory" IN (0, 1)), "default_value" TEXT NULL, "scanned_code_properties" TEXT NULL, "gs1_enabled" INTEGER NULL CHECK ("gs1_enabled" IN (0, 1)), "resource_type" TEXT NULL, "resource_metadata_schema" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "data_values" ("id" TEXT NOT NULL, "last_modified_date" TEXT NULL, "created_date" TEXT NULL, "data_element" TEXT NOT NULL REFERENCES data_elements (id), "data_instance" TEXT NOT NULL REFERENCES data_instances (id), "value" TEXT NULL, "comment" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "data_options" ("id" TEXT NOT NULL, "last_modified_date" TEXT NULL, "created_date" TEXT NULL, "display_name" TEXT NULL, "label" TEXT NULL, "translations" TEXT NOT NULL, "name" TEXT NOT NULL, "code" TEXT NOT NULL, "option_set" TEXT NOT NULL REFERENCES data_option_sets (id) ON UPDATE CASCADE ON DELETE CASCADE, "order" INTEGER NOT NULL, "deleted_at" TEXT NULL, PRIMARY KEY ("id"), UNIQUE ("option_set", "id"), UNIQUE ("option_set", "code"));
CREATE TABLE IF NOT EXISTS "user_form_permissions" ("team" TEXT NOT NULL REFERENCES teams (id), "form" TEXT NOT NULL REFERENCES form_templates (id), "valid_from" TEXT NULL, "valid_to" TEXT NULL, "permissions" TEXT NOT NULL, PRIMARY KEY ("team", "form"));
CREATE TABLE IF NOT EXISTS "sync_summaries" ("entity" TEXT NOT NULL, "last_sync" TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP), "success_count" INTEGER NOT NULL DEFAULT 0, "failure_count" INTEGER NOT NULL DEFAULT 0, "errors" TEXT NULL, PRIMARY KEY ("entity"));
CREATE INDEX org_name_idx ON org_units (name);
CREATE UNIQUE INDEX org_code_idx ON org_units (code);
CREATE UNIQUE INDEX org_path_idx ON org_units (path);
CREATE INDEX org_level_idx ON org_units (level);
CREATE INDEX level_name_idx ON ou_levels (name);
CREATE INDEX activity_disabled_idx ON activities (disabled);
CREATE INDEX team_cod_idx ON teams (code);
CREATE INDEX team_disabled_idx ON teams (disabled);
CREATE INDEX managed_team_cod_idx ON managed_teams (code);
CREATE INDEX assignment_status_idx ON assignments (status);
CREATE INDEX template_version_number_idx ON form_template_versions (version_number);
CREATE INDEX template_version_template_idx ON form_template_versions (template);
CREATE INDEX repeat_template_path_idx ON repeat_instances (template_path);
CREATE INDEX data_element_name_idx ON data_elements (name);
CREATE INDEX option_set_name_idx ON data_option_sets (name);
CREATE INDEX option_set_code_idx ON data_option_sets (code);
CREATE INDEX option_name_idx ON data_options (name);
CREATE INDEX option_code_idx ON data_options (code);
CREATE INDEX data_instance_status_idx ON data_instances (sync_state);
CREATE INDEX form_permission_form_idx ON user_form_permissions (team, form);
